from os import path

from taf.gnb.oam.coam.vdu.exceptions import ApiException
from taf.gnb.oam.coam.vdu.releases.vduoam22r4 import vDuOAM22R4
from taf.gnb.oam.coam.vdu.schemas.asm.get_operation_history_response import (
    OperationHistory,
)
from taf.gnb.oam.coam.vdu.schemas.asm.plan_tree_diff_v1 import MoLiteCurrentPlan
from taf.gnb.oam.coam.vdu.schemas.asm.nidd_response_v1 import NiddASMV1
from taf.gnb.oam.coam.vdu.schemas.asm.vdu_state_data_asm_v1 import VDUStateData
from taf.gnb.oam.coam.vdu.schemas.asm_licensed.get_snapshot_operations_information_v1 import (
    GetSnapshotOperationsInformationV1,
)
from taf.gnb.oam.coam.vdu.schemas.asm_licensed.vdu_cells_summary_v1 import VDUCellsSummaryLicensedV1
from taf.gnb.oam.coam.vdu.schemas.asm_licensed.vdu_state_data_v1 import VDUStateDataLicensedV1
from taf.gnb.oam.coam.vdu.schemas.cp_config_licensed.reset_vdu_v1 import (
    ResetVduLICENSEDV1,
)
from taf.gnb.oam.coam.vdu.schemas.cp_config_licensed.rf_diag_test_result import (
    RFDiagTestResult,
)
from taf.gnb.oam.coam.vdu.schemas.pm.counters_value_v2 import CounterValuePMV2
from taf.gnb.oam.coam.vdu.schemas.vdu_licensed.rf_stat_diag_test_result import (
    RFStatDiagTestResult,
)
from taf.gnb.oam.coam.vdu.services.asm_licensed.asm_licensed_v1 import ASMLICENSEDv1
from taf.gnb.oam.coam.vdu.services.pm.pm_v2 import PMv2
from taf.gnb.oam.coam.vdu.services.fh_licensed.fh_licensed_v1 import FHLicensedv1
from taf.gnb.oam.coam.vdu.services.emservice.emservice_v1 import EMServicev1
from taf.gnb.oam.coam.vdu.schemas.vdu.reset_rmod_response import ResetRmodsResponse
from taf.gnb.oam.coam.vdu.utilities.poll_status import poll_status
from taf.gnb.oam.coam.vdu.utilities.use_m2m_parser import enforce_use_m2m_type


class vDuOAM23R1(vDuOAM22R4):
    def __init__(self, con_details, need_all_info=False):
        super(vDuOAM23R1, self).__init__(con_details, need_all_info)
        self.pm_v2 = PMv2(con_details=con_details)
        self.asm_licensed_v1 = ASMLICENSEDv1(con_details=con_details)
        self.fh_licensed_v1 = FHLicensedv1(con_details=con_details)
        self.emservice_v1 = EMServicev1(con_details=self.con_details)

    @enforce_use_m2m_type
    def start_rf_diagnostic_test(self, nr_cell_id=-1, act_remote_rf_diag=True, rx_antenna_rssi_high_threshold=-30,
                                 rx_antenna_rssi_low_threshold=-110, tx_antenna_vswr_high_threshold=3, timeout=60,
                                 **kwargs):
        self.cp_config_licensed.start_rf_diagnostic_test(
            nr_cell_id=nr_cell_id,
            rx_antenna_rssi_high_threshold=rx_antenna_rssi_high_threshold,
            rx_antenna_rssi_low_threshold=rx_antenna_rssi_low_threshold,
            tx_antenna_vswr_high_threshold=tx_antenna_vswr_high_threshold,
            act_remote_rf_diag=act_remote_rf_diag,
            timeout=timeout)

    @enforce_use_m2m_type
    def get_diagnostic_rf_diagnostic_test_results(self, timeout=60, raw=False):
        response = self.cp_config_licensed.get_diagnostic_rf_diagnostic_test_results(timeout=timeout)
        return response if raw else RFDiagTestResult.from_object_dict(response)

    @enforce_use_m2m_type
    def start_diagnostic_rf_statistics_diagnostic_test(self, target_rmod_id=-1, act_remote_rf_diag=True, rf_temperature_high_threshold=80,
                                                       rf_temperature_low_threshold=-5, timeout=60):
        self.fh_licensed_v1.start_diagnostic_rf_statistics_diagnostic_test(target_rmod_id=target_rmod_id,
                                                                           rf_temperature_high_threshold=rf_temperature_high_threshold,
                                                                           rf_temperature_low_threshold=rf_temperature_low_threshold,
                                                                           act_remote_rf_diag=act_remote_rf_diag,
                                                                           timeout=timeout)

    @enforce_use_m2m_type
    def get_diagnostic_rf_statistics_diagnostic_test_results(self, timeout=60, raw=False):
        response = self.fh_licensed_v1.get_diagnostic_rf_statistics_diagnostic_test_results(timeout=timeout)
        return response if raw else RFStatDiagTestResult.from_object_dict(response)

    def get_operation_history(self, timeout=30):
        response = self.asm_v1.get_operation_history(timeout=timeout)
        return list(map(OperationHistory.from_object_dict, response))

    @enforce_use_m2m_type
    def get_snapshot_operations_information(self, timeout=30, raw=False):
        raw_response = self.asm_licensed.get_snapshot_operations_information(timeout=timeout)

        return raw_response if raw else GetSnapshotOperationsInformationV1.from_object_dict(raw_response)

    @enforce_use_m2m_type
    def check_snapshot_status(self, timeout=30, use_m2m=True):
        if use_m2m:
            res = self.asm_licensed.check_snapshot_status(timeout=timeout)
        else:
            res = self.asm_v1.check_snapshot_status(timeout=timeout)
        return res["status"]

    def clear_rf_diagnostic_test_results(self, timeout=30):
        return self.cp_config.clear_rf_diagnostic_test_results(timeout=timeout)

    def clear_rf_statistics_diagnostic_test_results(self, timeout=30):
        return self.fh_v1.clear_rf_statistics_diagnostic_test_results(timeout=timeout)

    def perform_commissioning(self, scf_file, wait_for_completion, should_activate=True, timeout=300):
        try:
            return self.asm_licensed_v1.perform_commissioning(scf_file=scf_file, wait_for_completion=wait_for_completion,
                                                              should_activate=should_activate, timeout=timeout)
        except ApiException as e:
            if "Machine-to-Machine interface was disabled" in e.body:
                return self._perform_commissioning_using_internal_api(scf_file=scf_file,
                                                                      wait_for_completion=wait_for_completion,
                                                                      timeout=timeout)
            else:
                raise e

    def _perform_commissioning_using_internal_api(self, scf_file, wait_for_completion, timeout):
        try:
            return self.asm_v1.perform_commissioning(scf_file=scf_file, wait_for_completion=wait_for_completion,
                                                     timeout=timeout)
        except ApiException as e:
            # due to CB012840 /api/asm/v1/staged-plans might be unavailable then /api/emservice/v1/staged-plans
            # should be used instead
            if "No API found with those values API" in e.body:
                return self._combine_asm_and_emservice_api_to_perform_commissioning(
                    scf_file=scf_file, wait_for_completion=wait_for_completion, timeout=timeout)
            else:
                raise e

    def _combine_asm_and_emservice_api_to_perform_commissioning(self, scf_file, wait_for_completion, timeout):
        plan_name = path.splitext(path.split(scf_file)[1])[0]

        self.asm_v1.add_plan_to_staging(scf_file=scf_file, plan_name=plan_name, timeout=timeout)
        staged_plans = self.emservice_v1.get_staged_plans()
        operation = self.asm_v1.activate_staged_plan(staged_plans=staged_plans, plan_name=plan_name,
                                                     timeout=timeout)
        if wait_for_completion:
            method_name = "get_status_of_perform_commissioning"

            return poll_status(instance=self.asm_v1.local_client, method_name=method_name,
                               operation_id=operation["id"], timeout=timeout, plan_id=operation["planId"])

        return operation

    def get_status_of_perform_commissioning(self, operation_id, timeout=30, should_activate=True):
        return self.asm_licensed_v1.get_status_of_perform_commissioning(operation_id=operation_id, timeout=timeout,
                                                                        should_activate=should_activate)

    @enforce_use_m2m_type
    def get_cell_specific_info(self, cell_id, timeout=30):
        return self.asm_licensed_v1.get_cell_specific_info(cell_id=cell_id, timeout=timeout)

    @enforce_use_m2m_type
    def reset_vdu(self, timeout=60, use_m2m=True, graceful_cell_shutdown=False, raw=False):
        if use_m2m:
            reset_vdu = self.cp_config_licensed.reset_vdu(timeout=timeout, graceful_cell_shutdown=graceful_cell_shutdown)
        else:
            reset_vdu = self.cp_config.reset_vdu(timeout=timeout, graceful_cell_shutdown=graceful_cell_shutdown)

        return reset_vdu if raw else ResetVduLICENSEDV1.from_object_dict(reset_vdu)

    @enforce_use_m2m_type
    def get_reset_vdu_operation_status(self, operation_id, timeout=30, use_m2m=True, raw=False):
        if use_m2m:
            reset_vdu_status = self.cp_config_licensed.get_reset_vdu_operation_status(operation_id=operation_id,
                                                                                      timeout=timeout)
        else:
            reset_vdu_status = self.cp_config.get_reset_vdu_operation_status(operation_id=operation_id,
                                                                             timeout=timeout)

        return reset_vdu_status if raw else ResetVduLICENSEDV1.from_object_dict(reset_vdu_status)

    def perform_delta_recommissioning(self, delta_file, wait_for_completion=True, should_activate=True, timeout=300):
        return self.asm_licensed_v1.perform_delta_recommissioning(delta_file=delta_file,
                                                                  wait_for_completion=wait_for_completion,
                                                                  should_activate=should_activate,
                                                                  timeout=timeout,
                                                                  nidd_info=self.get_nidd())

    def get_status_of_perform_delta_recommissioning(self, operation_id, timeout=30, should_activate=True):
        return self.asm_licensed_v1.get_status_of_perform_delta_recommissioning(operation_id=operation_id,
                                                                                timeout=timeout,
                                                                                should_activate=should_activate)

    @enforce_use_m2m_type
    def get_vdu_state_data(self, use_m2m=True, raw=False):
        if use_m2m:
            vdu_state_data = self.asm_licensed_v1.get_vdu_state_data()
            return vdu_state_data if raw else VDUStateDataLicensedV1.from_object_dict(vdu_state_data)
        else:
            vdu_state_data = self.asm_v1.get_vdu_state_data()
            return vdu_state_data if raw else VDUStateData.from_object_dict(vdu_state_data)

    @enforce_use_m2m_type
    def reset_rmods(self, rmods_list, reset_reason='user', graceful_cell_shutdown=False, timeout=30, raw=False, wait_for_completion=False,
                    use_m2m=True):
        if use_m2m:
            reset_res = self.fh_licensed_v1.reset_rmods(rmods_list=rmods_list, reset_reason=reset_reason,
                                                        graceful_cell_shutdown=graceful_cell_shutdown, wait_for_completion=wait_for_completion,
                                                        timeout=timeout)
        else:
            reset_res = self.fh_v1.reset_rmods(rmods_list=rmods_list, reset_reason=reset_reason,
                                               graceful_cell_shutdown=graceful_cell_shutdown, wait_for_completion=wait_for_completion,
                                               timeout=timeout)

        return reset_res if raw else ResetRmodsResponse.from_object_dict(reset_res)

    @enforce_use_m2m_type
    def get_reset_rmods_operation_status(self, operation_id, timeout=30, raw=False, use_m2m=True):
        if use_m2m:
            reset_operation_status = self.fh_licensed_v1.get_reset_rmods_operation_status(operation_id=operation_id,
                                                                                          timeout=timeout)
        else:
            reset_operation_status = self.fh_v1.get_reset_rmods_operation_status(operation_id=operation_id,
                                                                                 timeout=timeout)

        return reset_operation_status if raw else ResetRmodsResponse.from_object_dict(reset_operation_status)

    @enforce_use_m2m_type
    def get_cells_summary(self, use_m2m=True, timeout=30, raw=False):
        if use_m2m:
            cells_summary = self.asm_licensed_v1.get_cells_summary(timeout=timeout)
        else:
            cells_summary = self.asm_v1.get_cells_summary(timeout=timeout)

        return cells_summary if raw else VDUCellsSummaryLicensedV1.from_object_dict(cells_summary)

    def get_counter_values(self, counter_id, dimension_dn, raw=False, **kwargs):
        counter_values = self.pm_v2.get_counter_values(counter_id=counter_id, dimension_dn=dimension_dn, **kwargs)
        return counter_values if raw else self._process_counter_values(counter_values, counter_id, dimension_dn)

    @staticmethod
    def _process_counter_values(counter_values, counter_id, dimension_dn):
        counter_name = f"{counter_id}:{dimension_dn}"
        return CounterValuePMV2.from_object_dict(counter_values[counter_name])

    def get_nidd(self, need_nidd_version=False, raw=False):
        nidd_info = self.asm_v1.get_nidd()

        if raw:
            return nidd_info
        else:
            processed_info = NiddASMV1.from_object_dict(nidd_info)
            return processed_info if need_nidd_version else processed_info["managed_objects"]

    def get_tree_of_current_plan(self, timeout=30, raw=False):
        tree_info = self.asm_v1.get_tree_of_current_plan(timeout=timeout)

        return tree_info if raw else MoLiteCurrentPlan.from_object_dict(tree_info["created"])
